FirOp fir_cf_if_begin(struct FirBuilder *fb,
                      const FirType *results,
                      size_t nresults,
                      FirValue cond);

// `cf.loop [progress] [iter(…)] { … }`: one region whose parameters are the loop state.
//
// Makes the op with empty regions: fill them with `fir_position_at_end`.
