FirOp fir_cf_cond_br(struct FirBuilder *fb, FirValue cond, struct FirTarget t, struct FirTarget f);

// `cf.switch %v, default ^d(…), [k: ^b(…), …]`: jump to the case whose key is `%v` (keys are
